package pk.edu.dsu.scd.lab03;import java.util.*;public final class ArrayStack<T> implements Stack<T>{private Object[] a=new Object[8];private int n;public void push(T x){if(n==a.length)a=Arrays.copyOf(a,a.length*2);a[n++]=x;}public T pop(){if(isEmpty())throw new NoSuchElementException();T x=at(--n);a[n]=null;return x;}public T peek(){if(isEmpty())throw new NoSuchElementException();return at(n-1);}@SuppressWarnings("unchecked")private T at(int i){return(T)a[i];}public boolean isEmpty(){return n==0;}public int size(){return n;}}